ORDER = ['define', 'collect', 'clean', 'explore', 'model', 'evaluate', 'deploy', 'monitor']

n = int(input())
hours = {}
ignored = 0
for _ in range(n):
    parts = input().split(',')
    if len(parts) != 2:
        ignored += 1
        continue
    stage = parts[0].strip().lower()
    try:
        h = float(parts[1])
    except ValueError:
        ignored += 1
        continue
    if stage not in ORDER or h < 0:
        ignored += 1
        continue
    hours[stage] = hours.get(stage, 0.0) + h

total = sum(hours.values())
if total == 0:
    print('No valid tasks')
else:
    for stage in ORDER:
        if stage in hours:
            print(f'{stage}: {hours[stage]:.1f}h ({100 * hours[stage] / total:.1f}%)')
    bottleneck = max(ORDER, key=lambda s: (hours.get(s, -1), -ORDER.index(s)))
    print(f'Bottleneck: {bottleneck}')
missing = [s for s in ORDER if s not in hours]
print('Missing stages: ' + (', '.join(missing) if missing else 'none'))
print(f'Ignored: {ignored}')

